Given a string and a position (0-based indexing), remove the character at the given position.Examples: Input : s = "abcde",  pos = 1Output : s = "acde"Input : s = "a",  pos = 0Output : s = ""Try It YourselfApproach - By Using Built-In MethodsWe use erase in C++, string slicing in Python, StringBuilder Delete in Java, substring in Java and slice in JavaScript.
            C++

    #include <bits/stdc++.h>
using namespace std;

string removeCharAtPosition(string s, int pos) {
    if (pos < 0 || pos >= s.length()) {
        return s;
    }
    s.erase(pos, 1);
    return s;
}

int main() {
    string s = "abcde";
    int pos = 1;
    cout << "Output: " << removeCharAtPosition(s, pos) << endl; 
    return 0;
}


            C

    #include <stdio.h>
#include <string.h>

void removeCharAtPosition(char *s, int pos) {
    int len = strlen(s);
    if (pos < 0 || pos >= len) {
        return;
    }
    memmove(&s[pos], &s[pos + 1], len - pos);
}

int main() {
    char s[] = "abcde";
    int pos = 1;
    removeCharAtPosition(s, pos);
    printf("Output: %s\n", s);
    return 0;
}


